    "about_heading": "भारताची राष्ट्रीय मानक संस्था",
    "about_p1": "भारतीय मानक ब्युरो (BIS) ही भारतीय मानक ब्युरो कायदा, 2016 अंतर्गत स्थापन झालेली वैधानिक संस्था आहे. ग्राहक व्यवहार, अन्न आणि सार्वजनिक वितरण मंत्रालयाच्या अंतर्गत कार्यरत, बीआयएस देशभरात मानकीकरण, गुणवत्ता चिन्हांकन आणि गुणवत्ता प्रमाणपत्राच्या विकासासाठी जबाबदार आहे.",
