    "preview_a": "आप बीआईएस केयर ऐप या मानकऑनलाइन पोर्टल के माध्यम से सीएम/एल लाइसेंस नंबर का उपयोग करके किसी भी उत्पाद लाइसेंस को रीयल-टाइम में सत्यापित कर सकते हैं। गुणवत्ता नियंत्रण आदेशों (क्यूसीओ) के तहत अधिसूचित उत्पादों को वैध बीआईएस लाइसेंस के बिना निर्मित, आयात या बेचा नहीं जा सकता।",
    "preview_ref": "बीआईएस अधिनियम 2016 • गुणवत्ता नियंत्रण आदेश (QCO) राजपत्र",
    "preview_try_asking": "सीधे पूछने का प्रयास करें:",
