    "preview_prompt_2": "आईएसआई मार्क प्राप्त करने के चरण",
    "about_tag": "भारतीय मानक ब्यूरो के बारे में",
    "about_heading": "भारत का राष्ट्रीय मानक निकाय",
    "about_p1": "भारतीय मानक ब्यूरो (BIS) भारतीय मानक ब्यूरो अधिनियम, 2016 के तहत स्थापित वैधानिक निकाय है। उपभोक्ता मामले, खाद्य और सार्वजनिक वितरण मंत्रालय के अधीन कार्यरत, बीआईएस भारत में वस्तुओं और सेवाओं के मानकीकरण, अंकन और गुणवत्ता प्रमाणीकरण के सुचारू विकास के लिए उत्तरदायी है।",
    "about_standardization_title": "मानकीकरण",
