    "about_obj_1_title": "उपभोक्ता संरक्षण:",
    "about_obj_1_desc": "सख्त परीक्षण और मानक अनुपालन के माध्यम से जनस्वास्थ्य और उपभोक्ताओं के हितों की रक्षा करना।",
