// Case-insensitive normalized map for fast flexible phrase matching
const NORMALIZED_MAP = {}
for (const [phrase, trans] of Object.entries(UNIVERSAL_TERMS)) {
  NORMALIZED_MAP[phrase.toLowerCase().trim()] = trans
}

// Helper to get translated string with comprehensive 3-tier fallback chain
export const getTranslation = (key, lang = 'en') => {
  if (!key) return ''
  if (lang === 'en') {
    return TRANSLATIONS.en?.[key] || key
  }

  // Tier 1: Check primary dictionary
  if (TRANSLATIONS[lang] && TRANSLATIONS[lang][key]) {
    return TRANSLATIONS[lang][key]
  }

  // Tier 2: Check exact match in universal terminology
  if (UNIVERSAL_TERMS[key] && UNIVERSAL_TERMS[key][lang]) {
    return UNIVERSAL_TERMS[key][lang]
  }

  // Tier 3: Check case-insensitive normalized terms
  const normKey = String(key).toLowerCase().trim()
  if (NORMALIZED_MAP[normKey] && NORMALIZED_MAP[normKey][lang]) {
    return NORMALIZED_MAP[normKey][lang]
  }

  // Fallback to English dictionary or key itself
  if (TRANSLATIONS.en && TRANSLATIONS.en[key]) {
    return TRANSLATIONS.en[key]
  }
  return key
}

// React hook for easy reactive translation across any component
export function useTranslation() {
  const preferredLanguage = useSettingsStore((s) => s.preferredLanguage) || 'en'
  const setPreferredLanguage = useSettingsStore((s) => s.setPreferredLanguage)

  const t = (key, fallback) => {
    if (!key) return ''
    if (preferredLanguage === 'en') {
      return TRANSLATIONS.en?.[key] || fallback || key
    }

    const val = getTranslation(key, preferredLanguage)
    if (val && val !== key) return val

    // If key didn't yield a translation, try translating the fallback phrase!
    if (fallback && fallback !== key) {
      const fbVal = getTranslation(fallback, preferredLanguage)
      if (fbVal && fbVal !== fallback) return fbVal
    }

    return fallback || key
  }

  return {
    t,
    language: preferredLanguage,
    setLanguage: setPreferredLanguage,
  }
}

export default useTranslation
